"""
WEB - Servicios: puente entre el almacén de datos y el MODELO del curso.
Cada función lee el almacén, arma la estructura propia (Grafo, Trie, MaxHeap,
grafo de conflictos...) y corre el algoritmo. Es el mismo código de la versión Flask,
solo que en vez de consultas SQL lee listas y diccionarios (ver almacen.py).
"""
import json
import math
import os
from datetime import datetime

from model.grafo import Grafo, Vertice
from model import busqueda as bus
from model import coloracion as col
from model import tsp as tsp_mod
from model import vertex_cover as vc
from model.trie import Trie
from model.heap import MaxHeap, Reporte

RAIZ = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Coordenadas aproximadas (centro de cada localidad de Bogota) para la ruta de premios
LOCALIDADES = {
    "Usaquén": (4.7030, -74.0300), "Chapinero": (4.6486, -74.0628), "Santa Fe": (4.6000, -74.0700),
    "San Cristóbal": (4.5700, -74.0900), "Usme": (4.4800, -74.1200), "Tunjuelito": (4.5750, -74.1350),
    "Bosa": (4.6150, -74.1860), "Kennedy": (4.6300, -74.1530), "Fontibón": (4.6780, -74.1420),
    "Engativá": (4.7090, -74.1120), "Suba": (4.7410, -74.0840), "Barrios Unidos": (4.6680, -74.0760),
    "Teusaquillo": (4.6440, -74.0930), "Los Mártires": (4.6060, -74.0900), "Antonio Nariño": (4.5900, -74.1000),
    "Puente Aranda": (4.6150, -74.1150), "La Candelaria": (4.5960, -74.0730), "Rafael Uribe Uribe": (4.5730, -74.1150),
    "Ciudad Bolívar": (4.5100, -74.1500),
}
SERVIDORES = [f"S-LATAM-{i}" for i in range(1, 8)]
MOTIVOS = {"Discurso de odio": 90, "Contenido violento": 85, "Acoso o bullying": 80, "Suplantación": 70,
           "Spam o estafa": 60, "Otro": 30, "Spoilers sin aviso": 20}
FRANJA_INICIO, FRANJA_MINUTOS = 18 * 60, 90          # turno 1 = 6:00 pm, cada turno dura 1 h 30 min
BODEGA = {"nombre": "Bodega Gamefolks", "localidad": "Chapinero", "lat": 4.6486, "lon": -74.0628}
MAX_OPTIMO_VC = 16


def _catalogo():
    with open(os.path.join(RAIZ, "data", "red_gamefolks.json"), encoding="utf-8") as f:
        return json.load(f)["catalogo"]


def _usuarios(con):
    return {u["id"]: dict(u) for u in con.usuarios_ordenados()}


def grafo_desde_db(con):
    """Grafo DIRIGIDO 'sigue a' con lista de adyacencia propia (model.grafo.Grafo)."""
    g = Grafo(dirigido=True)
    for u in _usuarios(con).values():
        g.AñadirVertice(Vertice(u["id"], u["usuario"], juego=u["juego"], localidad=u["localidad"],
                                lat=u["lat"], lon=u["lon"], x=u["x"], y=u["y"]))
    for r in con.seguimientos:
        g.Union(r["origen"], r["destino"], r["peso"], capacidad=r["capacidad"])
    return g


def _mini(g, i):
    v = g.vertices[i]
    return {"id": i, "usuario": v.nombre, "juego": v.datos.get("juego", "")}


# ---------------------------------------------------------------- BFS
def sugerencias(con, yo, cuantas=6):
    g = grafo_desde_db(con)
    niveles, padre = bus.bfs_niveles(g.adyacencia, yo, max_nivel=3, con_padres=True)
    sigo = {v for v, _ in g.adyacencia[yo]}
    salida = []
    for nivel in (2, 3):
        for i in niveles.get(nivel, []):
            if i != yo and i not in sigo:
                medio = padre[i]
                while padre[medio] != yo and padre[medio] is not None:
                    medio = padre[medio]
                salida.append({**_mini(g, i), "nivel": nivel, "por_medio_de": g.vertices[padre[i]].nombre,
                               "amigo_directo": g.vertices[medio].nombre})
    if len(salida) < cuantas:                           # relleno: los mas seguidos que aun no sigo
        ya = {s["id"] for s in salida} | sigo | {yo}
        populares = sorted((i for i in g.vertices if i not in ya), key=lambda i: -g.GradoEntrada(i))
        salida += [{**_mini(g, i), "nivel": None, "por_medio_de": None, "amigo_directo": None,
                    "seguidores": g.GradoEntrada(i)} for i in populares]
    return {"niveles": {k: [_mini(g, i) for i in v] for k, v in niveles.items()}, "sugerencias": salida[:cuantas]}


# ---------------------------------------------------------------- UCS + BFS
def ruta(con, yo, hasta):
    g = grafo_desde_db(con)
    if hasta not in g.vertices:
        raise ValueError("Ese usuario no existe.")
    if hasta == yo:
        raise ValueError("Elige a otra persona: esa ruta eres tú.")
    salida = {}
    for alg in ("UCS", "BFS"):
        r = bus.ALGORITMOS[alg](g.adyacencia, yo, hasta)
        tramos = [{"desde": g.vertices[a].nombre, "hasta": g.vertices[b].nombre, "costo": dict(g.adyacencia[a])[b]}
                  for a, b in zip(r["camino"], r["camino"][1:])] if r["camino"] else []
        salida[alg] = {"camino": [_mini(g, i) for i in r["camino"]] if r["camino"] else None, "costo": r["costo"],
                       "saltos": r["saltos"], "expandidos": len(r["expandidos"]), "tramos": tramos}
    return salida


# ---------------------------------------------------------------- DFS
def ciclos(con, yo):
    g = grafo_desde_db(con)
    todos = bus.detectar_ciclos_dfs(g.adyacencia)
    mios = [c for c in todos if yo in c]
    return {"mios": [[g.vertices[i].nombre for i in c] for c in mios],
            "total": len(todos), "todos": [[g.vertices[i].nombre for i in c] for c in todos]}


# ---------------------------------------------------------------- Trie
def buscar(con, q):
    q = (q or "").strip()
    if len(q) < 2:
        return {"usuarios": [], "juegos": []}
    g = grafo_desde_db(con)
    t_usuarios, por_nombre = Trie(), {}
    for i, v in g.vertices.items():
        t_usuarios.insertar(v.nombre, g.GradoEntrada(i))
        por_nombre[v.nombre] = i
    t_juegos = Trie()
    for juego in _catalogo():
        t_juegos.insertar(juego["nombre"], juego["popularidad"])
    usuarios = [{**_mini(g, por_nombre[n]), "seguidores": p} for n, p in t_usuarios.autocompletar_top_k(q, 5)]
    juegos = [{"nombre": n, "popularidad": p} for n, p in t_juegos.autocompletar_top_k(q, 5)]
    return {"usuarios": usuarios, "juegos": juegos}


def juegos_populares(cuantos=6):
    return sorted(_catalogo(), key=lambda j: -j["popularidad"])[:cuantos]


# ---------------------------------------------------------------- Welsh-Powell
def _eventos(con):
    return {e["id"]: {**e, "participantes": [u for ev, u in con.participantes if ev == e["id"]]}
            for e in con.eventos_ordenados()}


def _hora(minutos):
    h, m = divmod(minutos, 60)
    sufijo = "pm" if h >= 12 else "am"
    return f"{(h - 1) % 12 + 1}:{m:02d} {sufijo}"


def horario_eventos(con):
    eventos = _eventos(con)
    usuarios = _usuarios(con)
    nombres = {i: u["usuario"] for i, u in usuarios.items()}
    lista = [{"id": e["id"], "nombre": e["nombre"], "juego": e["juego"], "servidor": e["servidor"],
              "participantes": [nombres.get(p, p) for p in e["participantes"]]} for e in eventos.values()]
    if not eventos:
        return {"eventos": [], "turnos": [], "n_turnos": 0, "conflictos": []}
    grafo = col.construir_grafo_conflictos(eventos)
    grados = col.calcular_grados(grafo)
    orden = col.ordenar_por_grado(grados)
    color = col.welsh_powell(grafo, orden)
    turnos = []
    for t, evs in col.agrupar_por_turno(color).items():
        ini = FRANJA_INICIO + (t - 1) * FRANJA_MINUTOS
        turnos.append({"turno": t, "inicio": _hora(ini), "fin": _hora(ini + FRANJA_MINUTOS),
                       "eventos": [{"id": e, "nombre": eventos[e]["nombre"]} for e in evs]})
    for e in lista:
        e["grado"], e["turno"] = grados[e["id"]], color[e["id"]]
    conflictos = [{"a": a, "b": b, "motivo": col.motivo_conflicto(eventos, a, b, nombres)}
                  for a in grafo for b in grafo[a] if a < b]
    return {"eventos": lista, "turnos": turnos, "n_turnos": max(color.values()), "orden": orden,
            "valida": col.es_coloracion_valida(grafo, color), "conflictos": conflictos}


def crear_evento(con, creador, nombre, juego, servidor, participantes):
    nombre = (nombre or "").strip()
    if not nombre:
        raise ValueError("El evento necesita un nombre.")
    if servidor not in SERVIDORES:
        raise ValueError("Elige un servidor de la lista.")
    usuarios = _usuarios(con)
    participantes = list(dict.fromkeys(p for p in participantes if p in usuarios))
    if not participantes:
        raise ValueError("Elige al menos un participante.")
    eid = con.siguiente_id_evento()
    con.eventos[eid] = {"id": eid, "nombre": nombre[:60], "juego": (juego or "").strip()[:40],
                        "servidor": servidor, "creador": creador}
    con.participantes.extend([eid, p] for p in participantes)
    return eid


# ---------------------------------------------------------------- TSP
def premios(con, ganadores):
    usuarios = _usuarios(con)
    ganadores = list(dict.fromkeys(g for g in ganadores if g in usuarios))
    if not ganadores:
        raise ValueError("Elige al menos un ganador.")
    sin_ubicacion = [usuarios[g]["usuario"] for g in ganadores if usuarios[g]["lat"] is None]
    if sin_ubicacion:
        raise ValueError(f"Estos usuarios no tienen localidad: {', '.join(sin_ubicacion)}.")
    puntos = [("BODEGA", BODEGA["lat"], BODEGA["lon"])] + [(g, usuarios[g]["lat"], usuarios[g]["lon"]) for g in ganadores]
    d = tsp_mod.matriz_distancias(puntos)
    ids = [p[0] for p in puntos]
    aprox = tsp_mod.tsp_aproximado_mst(ids, d)
    try:
        exacto = tsp_mod.tsp_exacto(ids, d)
    except ValueError:
        exacto = None

    def info(i):
        if i == "BODEGA":
            return {"id": i, "nombre": BODEGA["nombre"], "localidad": BODEGA["localidad"], "lat": BODEGA["lat"], "lon": BODEGA["lon"]}
        u = usuarios[i]
        return {"id": i, "nombre": u["usuario"], "localidad": u["localidad"], "lat": u["lat"], "lon": u["lon"]}

    return {"puntos": [info(i) for i in ids],
            "aprox": {"ruta": aprox["ruta"], "km": aprox["costo"], "mst": [[a, b] for a, b, _ in aprox["aristas_mst"]],
                      "km_mst": aprox["peso_mst"]},
            "exacto": {"ruta": exacto["ruta"], "km": exacto["costo"], "probadas": exacto["rutas_probadas"]} if exacto else None,
            "razon": round(aprox["costo"] / exacto["costo"], 3) if exacto and exacto["costo"] else None,
            "tramos": [{"desde": info(a)["nombre"], "hasta": info(b)["nombre"], "km": d[(a, b)]}
                       for a, b in zip(aprox["ruta"], aprox["ruta"][1:])]}


# ---------------------------------------------------------------- Heap (moderacion)
def _heap_pendientes(con):
    """Prioridad = gravedad del motivo + 5 puntos por cada dia pendiente (envejecimiento)."""
    heap, info = MaxHeap(), {}
    ahora = datetime.now()
    reportes = []
    for r in con.reportes:
        pub = con.publicacion(r["publicacion"])
        if r["estado"] != "pendiente" or not pub:
            continue
        dias = (ahora - datetime.fromisoformat(r["creado"])).days
        prioridad = r["gravedad"] + 5 * dias
        reportes.append(Reporte(str(r["id"]), prioridad, r["motivo"]))
        info[str(r["id"])] = {"id": r["id"], "motivo": r["motivo"], "gravedad": r["gravedad"], "dias": dias,
                              "prioridad": prioridad, "publicacion": r["publicacion"], "texto": pub["texto"],
                              "autor": con.usuarios[pub["autor"]]["usuario"],
                              "reportero": con.usuarios[r["reportero"]]["usuario"]}
    heap.construir_heap(reportes)
    return heap, info


def cola_moderacion(con):
    heap, info = _heap_pendientes(con)
    orden = []
    while not heap.esta_vacio():                       # extraer todo = orden de atencion (heap sort)
        orden.append(info[heap.extraer_max().id_reporte])
    return orden


def atender_siguiente(con, accion):
    if accion not in ("eliminar", "descartar"):
        raise ValueError("Acción no válida.")
    heap, info = _heap_pendientes(con)
    r = heap.extraer_max()
    if r is None:
        raise ValueError("No hay reportes pendientes. 🎉")
    dato = info[r.id_reporte]
    if accion == "eliminar":
        for rep in con.reportes:
            if rep["publicacion"] == dato["publicacion"]:
                rep["estado"] = "atendido"
        con.borrar_publicacion(dato["publicacion"])
    else:
        for rep in con.reportes:
            if rep["id"] == dato["id"]:
                rep["estado"] = "atendido"
    return dato


# ---------------------------------------------------------------- Vertex Cover
def monitorear(con):
    g = grafo_desde_db(con)
    aristas = vc.aristas_sin_direccion(g)
    if not aristas:
        return {"aprox": [], "elegidas": [], "optimo": None, "interacciones": 0}
    aprox, elegidas = vc.cobertura_aproximada(aristas)
    nodos = {x for a in aristas for x in a}
    optimo = vc.cobertura_optima(aristas) if len(nodos) <= MAX_OPTIMO_VC else None
    nom = lambda i: g.vertices[i].nombre
    return {"interacciones": len(aristas), "aprox": sorted(nom(i) for i in aprox),
            "elegidas": [[nom(u), nom(v)] for u, v in elegidas],
            "optimo": sorted(nom(i) for i in optimo) if optimo is not None else None,
            "valida": vc.es_cobertura(aristas, aprox)}


# ---------------------------------------------------------------- red para dibujar
def red(con):
    g = grafo_desde_db(con)
    sin_pos = [i for i, v in g.vertices.items() if v.datos.get("x") is None]
    nodos = []
    for i, v in g.vertices.items():
        x, y = v.datos.get("x"), v.datos.get("y")
        if x is None:                                   # usuarios nuevos: en un circulo alrededor
            k = sin_pos.index(i)
            ang = 2 * math.pi * k / max(1, len(sin_pos))
            x, y = 430 + 390 * math.cos(ang), 400 + 330 * math.sin(ang)
        nodos.append({"id": i, "usuario": v.nombre, "x": x, "y": y})
    aristas = [{"a": a, "b": b, "peso": p} for a, lista in g.adyacencia.items() for b, p in lista]
    return {"nodos": nodos, "aristas": aristas}

archivos.web/api.py:
"""
WEB - API de Gamefolks para GitHub Pages.
Las mismas rutas /api/... de la versión Flask, pero como un despachador en Python puro que
corre DENTRO del navegador (Pyodide). El frontend sigue usando fetch(); puente.js intercepta
las llamadas a /api/ y las pasa a manejar().
"""
import json
import re
from datetime import datetime
from urllib.parse import parse_qs, urlsplit

from . import laboratorio as lab, servicios as srv
from .almacen import Almacen, clave_correcta, hash_clave


class ErrorHttp(Exception):
    def __init__(self, estado, mensaje):
        super().__init__(mensaje)
        self.estado, self.mensaje = estado, mensaje


class Aplicacion:
    def __init__(self, datos_guardados=None):
        self.uid = None
        self.con = None
        if datos_guardados:
            try:
                guardado = json.loads(datos_guardados)
                self.con = Almacen.importar(guardado["datos"])
                self.uid = guardado.get("uid")
            except (ValueError, KeyError, TypeError):
                self.con = None
        if self.con is None:
            self.reiniciar()
        self.rutas = []
        self._registrar_rutas()

    # ------------------------------------------------ persistencia
    def reiniciar(self):
        self.con = Almacen().sembrar()
        self.uid = None
        lab._labs.clear()

    def exportar(self):
        return json.dumps({"datos": self.con.exportar(), "uid": self.uid}, ensure_ascii=False)

    # ------------------------------------------------ entrada
    def manejar(self, metodo, url, cuerpo_json=""):
        """-> JSON string {"estado": int, "cuerpo": ...}"""
        try:
            cuerpo = json.loads(cuerpo_json) if cuerpo_json else {}
            if not isinstance(cuerpo, dict):
                cuerpo = {}
        except ValueError:
            cuerpo = {}
        partes = urlsplit(url)
        consulta = {k: v[0] for k, v in parse_qs(partes.query).items()}
        try:
            for m, patron, funcion in self.rutas:
                if m != metodo:
                    continue
                encaje = patron.fullmatch(partes.path)
                if encaje:
                    estado, datos = funcion(cuerpo, consulta, **encaje.groupdict())
                    return json.dumps({"estado": estado, "cuerpo": datos}, ensure_ascii=False)
            raise ErrorHttp(404, "No encontrado.")
        except ErrorHttp as e:
            return json.dumps({"estado": e.estado, "cuerpo": {"error": e.mensaje}}, ensure_ascii=False)
        except ValueError as e:
            return json.dumps({"estado": 400, "cuerpo": {"error": str(e)}}, ensure_ascii=False)
        except Exception as e:                      # nunca se cae: responde 500 con el mensaje
            return json.dumps({"estado": 500, "cuerpo": {"error": f"Error interno: {e}"}}, ensure_ascii=False)

    # ------------------------------------------------ utilidades
    @staticmethod
    def ahora():
        return datetime.now().isoformat(timespec="seconds")

    def login_requerido(self):
        if not self.uid or self.uid not in self.con.usuarios:
            self.uid = None
            raise ErrorHttp(401, "Inicia sesión para continuar.")
        return self.uid

    def moderador_requerido(self):
        yo = self.login_requerido()
        if self.con.usuarios[yo]["rol"] != "moderador":
            raise ErrorHttp(403, "Solo los moderadores pueden ver esto.")
        return yo

    def perfil_publico(self, uid):
        c = self.con
        u = c.usuarios.get(uid)
        if not u:
            raise ValueError("Ese usuario no existe.")
        datos = {k: u[k] for k in ("id", "usuario", "bio", "juego", "localidad", "rol")}
        datos["seguidores"] = sum(1 for s in c.seguimientos if s["destino"] == uid)
        datos["siguiendo"] = sum(1 for s in c.seguimientos if s["origen"] == uid)
        datos["publicaciones"] = sum(1 for p in c.publicaciones if p["autor"] == uid)
        if self.uid:
            datos["lo_sigo"] = c.seguimiento(self.uid, uid) is not None
            datos["me_sigue"] = c.seguimiento(uid, self.uid) is not None
        return datos

    def publicaciones(self, filtro):
        c = self.con
        filas = []
        for p in c.publicaciones:
            if not filtro(p):
                continue
            filas.append({**p, "autor_nombre": c.usuarios[p["autor"]]["usuario"],
                          "autor_juego": c.usuarios[p["autor"]]["juego"],
                          "n_likes": sum(1 for l in c.likes if l[0] == p["id"]),
                          "n_comentarios": sum(1 for m in c.comentarios if m["publicacion"] == p["id"]),
                          "me_gusta": [p["id"], self.uid] in c.likes, "mia": p["autor"] == self.uid})
        filas.sort(key=lambda f: (f["creado"], f["id"]), reverse=True)
        return filas[:60]

    def _sumar_interaccion(self, pid, puntos):
        """Cada like o comentario suma al peso (interacciones/semana) del arco 'yo -> autor'."""
        p = self.con.publicacion(pid)
        if not p:
            raise ValueError("Esa publicación ya no existe.")
        s = self.con.seguimiento(self.uid, p["autor"])
        if s:
            s["peso"] += puntos

    def _comentarios(self, pid):
        c = self.con
        return [{**m, "autor_nombre": c.usuarios[m["autor"]]["usuario"]}
                for m in sorted((m for m in c.comentarios if m["publicacion"] == pid), key=lambda m: m["id"])]

    # ------------------------------------------------ rutas
    def _registrar_rutas(self):
        def ruta(metodo, patron):
            def deco(f):
                self.rutas.append((metodo, re.compile(patron), f))
                return f
            return deco

        # ---- sesión
        @ruta("POST", "/api/registro")
        def registro(d, q):
            usuario = (d.get("usuario") or "").strip()
            clave = d.get("clave") or ""
            localidad = d.get("localidad") or ""
            if not (3 <= len(usuario) <= 20) or not all(ch.isalnum() or ch == "_" for ch in usuario):
                raise ValueError("El usuario debe tener de 3 a 20 letras, números o guion bajo.")
            if len(clave) < 6:
                raise ValueError("La contraseña debe tener al menos 6 caracteres.")
            if localidad not in srv.LOCALIDADES:
                raise ValueError("Elige tu localidad (la usamos para enviarte premios).")
            if self.con.usuario_por_nombre(usuario):
                raise ValueError("Ese nombre de usuario ya está ocupado.")
            uid = self.con.siguiente_id_usuario()
            lat, lon = srv.LOCALIDADES[localidad]
            self.con.usuarios[uid] = {
                "id": uid, "usuario": usuario, "clave_hash": hash_clave(clave), "bio": (d.get("bio") or "")[:160],
                "juego": (d.get("juego") or "")[:40], "localidad": localidad, "lat": lat, "lon": lon,
                "x": None, "y": None, "rol": "usuario", "creado": self.ahora()}
            self.uid = uid
            return 201, self.perfil_publico(uid)

        @ruta("POST", "/api/login")
        def login(d, q):
            u = self.con.usuario_por_nombre((d.get("usuario") or "").strip())
            if not u or not clave_correcta(d.get("clave") or "", u["clave_hash"]):
                raise ValueError("Usuario o contraseña incorrectos.")
            self.uid = u["id"]
            return 200, self.perfil_publico(u["id"])

        @ruta("POST", "/api/logout")
        def logout(d, q):
            self.uid = None
            return 200, {"ok": True}

        @ruta("GET", "/api/yo")
        def mi_perfil(d, q):
            return 200, self.perfil_publico(self.login_requerido())

        @ruta("PUT", "/api/yo")
        def editar_perfil(d, q):
            yo = self.login_requerido()
            localidad = d.get("localidad")
            if localidad not in srv.LOCALIDADES:
                raise ValueError("Elige una localidad de la lista.")
            lat, lon = srv.LOCALIDADES[localidad]
            self.con.usuarios[yo].update(bio=(d.get("bio") or "")[:160], juego=(d.get("juego") or "")[:40],
                                         localidad=localidad, lat=lat, lon=lon)
            return 200, self.perfil_publico(yo)

        @ruta("GET", "/api/catalogos")
        def catalogos(d, q):
            return 200, {"localidades": list(srv.LOCALIDADES), "servidores": srv.SERVIDORES,
                         "motivos": list(srv.MOTIVOS)}

        # ---- publicaciones
        @ruta("GET", "/api/feed")
        def feed(d, q):
            yo = self.login_requerido()
            sigo = {s["destino"] for s in self.con.seguimientos if s["origen"] == yo}
            return 200, self.publicaciones(lambda p: p["autor"] == yo or p["autor"] in sigo)

        @ruta("GET", "/api/descubrir")
        def descubrir(d, q):
            self.login_requerido()
            return 200, self.publicaciones(lambda p: True)

        @ruta("POST", "/api/publicaciones")
        def publicar(d, q):
            yo = self.login_requerido()
            texto = (d.get("texto") or "").strip()
            if not texto:
                raise ValueError("Escribe algo antes de publicar.")
            if len(texto) > 400:
                raise ValueError("Máximo 400 caracteres.")
            p = self.con.nueva_publicacion(yo, texto, (d.get("juego") or "").strip()[:40], self.ahora())
            return 201, self.publicaciones(lambda x: x["id"] == p["id"])[0]

        @ruta("DELETE", r"/api/publicaciones/(?P<pid>\d+)")
        def borrar(d, q, pid):
            yo = self.login_requerido()
            pid = int(pid)
            p = self.con.publicacion(pid)
            if not p:
                raise ValueError("Esa publicación ya no existe.")
            if p["autor"] != yo and self.con.usuarios[yo]["rol"] != "moderador":
                raise ErrorHttp(403, "Solo puedes borrar tus publicaciones.")
            self.con.borrar_publicacion(pid)
            for r in self.con.reportes:
                if r["publicacion"] == pid:
                    r["estado"] = "atendido"
            return 200, {"ok": True}

        @ruta("POST", r"/api/publicaciones/(?P<pid>\d+)/like")
        def like(d, q, pid):
            yo = self.login_requerido()
            pid = int(pid)
            self._sumar_interaccion(pid, 0)
            par = [pid, yo]
            if par in self.con.likes:
                self.con.likes.remove(par)
                me_gusta = False
            else:
                self.con.likes.append(par)
                self._sumar_interaccion(pid, 1)
                me_gusta = True
            return 200, {"me_gusta": me_gusta, "n_likes": sum(1 for l in self.con.likes if l[0] == pid)}

        @ruta("GET", r"/api/publicaciones/(?P<pid>\d+)/comentarios")
        def ver_comentarios(d, q, pid):
            self.login_requerido()
            return 200, self._comentarios(int(pid))

        @ruta("POST", r"/api/publicaciones/(?P<pid>\d+)/comentarios")
        def comentar(d, q, pid):
            yo = self.login_requerido()
            pid = int(pid)
            texto = (d.get("texto") or "").strip()
            if not texto:
                raise ValueError("El comentario está vacío.")
            self._sumar_interaccion(pid, 2)
            self.con.nuevo_comentario(pid, yo, texto[:300], self.ahora())
            return 200, self._comentarios(pid)

        @ruta("POST", r"/api/publicaciones/(?P<pid>\d+)/reportar")
        def reportar(d, q, pid):
            yo = self.login_requerido()
            pid = int(pid)
            motivo = d.get("motivo")
            if motivo not in srv.MOTIVOS:
                raise ValueError("Elige un motivo de la lista.")
            if not self.con.publicacion(pid):
                raise ValueError("Esa publicación ya no existe.")
            if any(r["publicacion"] == pid and r["reportero"] == yo and r["estado"] == "pendiente"
                   for r in self.con.reportes):
                raise ValueError("Ya reportaste esta publicación. Los moderadores la están revisando.")
            self.con.nuevo_reporte(pid, yo, motivo, srv.MOTIVOS[motivo], self.ahora())
            return 200, {"ok": True}

        # ---- usuarios y seguir
        @ruta("GET", r"/api/usuarios/(?P<uid>[^/]+)")
        def ver_usuario(d, q, uid):
            self.login_requerido()
            return 200, {"perfil": self.perfil_publico(uid), "publicaciones": self.publicaciones(lambda p: p["autor"] == uid)}

        @ruta("POST", r"/api/usuarios/(?P<uid>[^/]+)/seguir")
        def seguir(d, q, uid):
            yo = self.login_requerido()
            if uid == yo:
                raise ValueError("No puedes seguirte a ti mismo.")
            if uid not in self.con.usuarios:
                raise ValueError("Ese usuario no existe.")
            s = self.con.seguimiento(yo, uid)
            if s:
                self.con.seguimientos.remove(s)
            else:
                self.con.seguimientos.append({"origen": yo, "destino": uid, "peso": 1, "capacidad": 10})
            return 200, self.perfil_publico(uid)

        @ruta("GET", "/api/usuarios")
        def lista_usuarios(d, q):
            self.login_requerido()
            return 200, [{k: u[k] for k in ("id", "usuario", "juego", "localidad")} for u in self.con.usuarios_ordenados()]

        # ---- algoritmos del curso
        @ruta("GET", "/api/buscar")
        def buscar(d, q):
            self.login_requerido()
            return 200, srv.buscar(self.con, q.get("q", ""))

        @ruta("GET", "/api/explorar")
        def explorar(d, q):
            yo = self.login_requerido()
            return 200, srv.sugerencias(self.con, yo) | {"juegos": srv.juegos_populares()}

        @ruta("GET", "/api/ruta")
        def ruta_ucs(d, q):
            yo = self.login_requerido()
            return 200, srv.ruta(self.con, yo, q.get("hasta", ""))

        @ruta("GET", "/api/ciclos")
        def ciclos(d, q):
            yo = self.login_requerido()
            return 200, srv.ciclos(self.con, yo)

        @ruta("GET", "/api/red")
        def red(d, q):
            self.login_requerido()
            return 200, srv.red(self.con)

        @ruta("GET", "/api/eventos")
        def eventos(d, q):
            self.login_requerido()
            return 200, srv.horario_eventos(self.con)

        @ruta("POST", "/api/eventos")
        def crear_evento(d, q):
            yo = self.login_requerido()
            srv.crear_evento(self.con, yo, d.get("nombre"), d.get("juego"), d.get("servidor"), d.get("participantes") or [])
            return 201, srv.horario_eventos(self.con)

        @ruta("POST", "/api/premios")
        def premios(d, q):
            self.login_requerido()
            return 200, srv.premios(self.con, d.get("ganadores") or [])

        @ruta("GET", "/api/moderacion")
        def moderacion(d, q):
            self.moderador_requerido()
            return 200, {"cola": srv.cola_moderacion(self.con), "monitorear": srv.monitorear(self.con)}

        @ruta("POST", "/api/moderacion/atender")
        def atender(d, q):
            self.moderador_requerido()
            hecho = srv.atender_siguiente(self.con, d.get("accion"))
            return 200, {"atendido": hecho, "cola": srv.cola_moderacion(self.con)}

        # ---- laboratorio (todos los talleres)
        @ruta("GET", "/api/lab/usuarios")
        def lab_usuarios(d, q):
            return 200, lab.usuarios(self.login_requerido())

        @ruta("POST", r"/api/lab/(?P<accion>[^/]+)")
        def lab_accion(d, q, accion):
            return 200, {"bloques": lab.ejecutar(self.login_requerido(), accion, d)}

